import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DGu13UIe.js";const d="/bagent/showcase/ama.png",c="/bagent/showcase/foodmap.png",n="/bagent/showcase/swiss.png",_=JSON.parse('{"title":"Agent 能做什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/showcase.md","filePath":"guide/showcase.md"}'),s={name:"guide/showcase.md"};function h(l,e,p,i,g,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-能做什么" tabindex="-1">Agent 能做什么 <a class="header-anchor" href="#agent-能做什么" aria-label="Permalink to &quot;Agent 能做什么&quot;">​</a></h1><p>三个在 <strong>VS Code / Cursor 插件</strong>里跑出来的真实对话截图。它们<strong>不只属于第 51 课</strong>——分别用到 <a href="/bagent/chapters/45-web-search.html">第 45 课</a> 联网、<a href="/bagent/chapters/49-str-replace.html">第 49 课</a> 局部改、<a href="/bagent/chapters/46-reminder-injection.html">第 46 课</a> plan 等；叠到 <a href="/bagent/chapters/51-run-command.html">第 51 课</a> 插件上，就是目前课程里<strong>最完整的一档代码 Agent</strong>。</p><p>自己试：从 <a href="/bagent/chapters/40-vscode-kernel-upgrade.html">第 40 课</a> 起跟到第 51 课，或 <code>npm run ch51:compile</code> 后 F5 打开 <code>lessons/51-run-command</code>。</p><hr><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>案例</th><th>任务</th><th>主要工具</th><th>相关课文</th></tr></thead><tbody><tr><td>A · 情书账本</td><td>查公开资料，写 HTML 小报</td><td><code>web_search</code> → <code>write_file</code></td><td><a href="/bagent/chapters/45-web-search.html">45</a>、<a href="/bagent/chapters/43-write-file.html">43</a></td></tr><tr><td>B · 京都食帖</td><td>精修已有美食地图页</td><td><code>str_replace</code></td><td><a href="/bagent/chapters/49-str-replace.html">49</a>、<a href="/bagent/chapters/48-read-lines.html">48</a></td></tr><tr><td>C · Swiss Table</td><td>用 C 实现哈希表并测试</td><td><code>plan_operate</code> → <code>write_file</code></td><td><a href="/bagent/chapters/46-reminder-injection.html">46</a>、<a href="/bagent/chapters/43-write-file.html">43</a></td></tr></tbody></table><p>写文件、改代码、查资料——<strong>不必等后续沙箱课</strong>。编译运行（<code>gcc</code>、<code>npm test</code>）仍建议在本地终端或等沙箱课再接上。</p><hr><h2 id="案例-a-查资料-写页面" tabindex="-1">案例 A：查资料 + 写页面 <a class="header-anchor" href="#案例-a-查资料-写页面" aria-label="Permalink to &quot;案例 A：查资料 + 写页面&quot;">​</a></h2><p><img src="'+d+'" alt="web_search 查票房与投资信息，再 write_file 生成 HTML"></p><p>用户要一份电影投资主题的 HTML 小报（《一封情书的账本》）。Agent 先用 <strong><code>web_search</code></strong> 查票房、成本、出品方、赞助商等公开信息，再 <strong><code>write_file</code></strong> 落成 <code>amam-report.html</code>——预览里的数字与机构名来自检索，不是瞎编。用户再说「艺术表达可以更大胆」，Agent 规划改字体、配色、破网格。</p><p><strong>侧重点是 search → write。</strong></p><hr><h2 id="案例-b-局部改前端" tabindex="-1">案例 B：局部改前端 <a class="header-anchor" href="#案例-b-局部改前端" aria-label="Permalink to &quot;案例 B：局部改前端&quot;">​</a></h2><p><img src="'+c+'" alt="str_replace 调圆角、加广告与分享按钮"></p><p>京都美食地图 <code>food-map.html</code> 已能跑（地图、餐厅卡片、评论）。用户提 UI：悬浮卡片圆角再精致一点、加点广告和社媒分享。Agent 连续 <strong><code>str_replace</code></strong> 改 CSS（<code>border-radius: 20px</code> → <code>10px</code> → <code>8px</code>），每次审批、只动匹配片段。</p><p><strong>侧重点是 read（行号）+ exact match 改代码。</strong></p><hr><h2 id="案例-c-多文件写-c" tabindex="-1">案例 C：多文件写 C <a class="header-anchor" href="#案例-c-多文件写-c" aria-label="Permalink to &quot;案例 C：多文件写 C&quot;">​</a></h2><p><img src="'+n+'" alt="plan 拆步 + write_file 写 swisstable.h/.c 与测试"></p><p>用户：「用 C 实现一个简单的 swisstable，并测试」。Agent <strong><code>plan_operate</code></strong> 拆三步：头文件 → 实现 → 测试与 benchmark；侧栏里逐步 <strong><code>write_file</code></strong> 落盘。终端里是本地 <code>gcc</code> 跑出的测试结果——Agent 负责写与拆任务，编译执行由你在终端完成（或等沙箱课）。</p><p><strong>侧重点是 plan + 多文件写入，语言不限于前端。</strong></p><hr><h2 id="还想继续" tabindex="-1">还想继续 <a class="header-anchor" href="#还想继续" aria-label="Permalink to &quot;还想继续&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>入口</th></tr></thead><tbody><tr><td>从零跟课</td><td><a href="/bagent/guide/how-to-learn.html">怎么学</a> · <a href="/bagent/chapters/01-deepseek.html">第 1 课</a></td></tr><tr><td>插件内核</td><td><a href="/bagent/chapters/40-vscode-kernel-upgrade.html">第 40 课</a> → <a href="/bagent/chapters/51-run-command.html">第 51 课</a></td></tr><tr><td>维护本站</td><td><a href="/bagent/development.html">维护文档站</a></td></tr></tbody></table>',25)])])}const f=t(s,[["render",h]]);export{_ as __pageData,f as default};
